/**
 * A small deterministic telemetry replay for CI. SYNTHETIC: generated by this
 * file to exercise partial frames, duplicates, out-of-order values, a
 * dropout, a disconnect and a reconnect that replays an old snapshot. It is
 * not a recording of the real feed (none could be taken from the sandbox
 * this was written in); replace it with a recorded session once the channel
 * mapping is validated.
 */
import type { ItemUpdate } from '../assembler.js';

export type ReplayEvent =
  | { at: number; kind: 'connection'; state: 'connecting' | 'connected' | 'disconnected' }
  | { at: number; kind: 'item'; update: ItemUpdate };

const ITEMS = ['A', 'B', 'C', 'D'];

/** One quaternion frame, source-stamped `srcDt` ms relative to the replay clock. */
const frame = (at: number, srcDt: number, q: number[]): ReplayEvent[] =>
  ITEMS.map((item, i) => ({ at, kind: 'item', update: { item, value: q[i], sourceTimeMs: at + srcDt } }));

/** `base` is the replay's local clock origin. Times are ms after it. */
export function syntheticSession(base: number): { events: ReplayEvent[]; expect: { accepted: number; staleRejected: number; outOfOrderRejected: number } } {
  const id = [1, 0, 0, 0];
  const yaw = [Math.SQRT1_2, 0, 0, Math.SQRT1_2];
  const events: ReplayEvent[] = [
    { at: 0, kind: 'connection', state: 'connecting' },
    { at: 100, kind: 'connection', state: 'connected' },
    // Three good one-second frames.
    ...frame(1000, -100, id), ...frame(2000, -100, id), ...frame(3000, -100, yaw),
    // A half frame, then its remainder landing after the next frame started.
    { at: 4000, kind: 'item', update: { item: 'A', value: 1, sourceTimeMs: 4000 - 100 } },
    { at: 4010, kind: 'item', update: { item: 'B', value: 0, sourceTimeMs: 4000 - 100 } },
    ...frame(5000, -100, id),
    // The same frame again, and an older one: neither is shown as new.
    ...frame(5001, -101, id), // same source time as the 5000 frame (4900)
    ...frame(5002, -2000, id),
    // Dropout, then a disconnect and a reconnect whose MERGE snapshot replays old values.
    { at: 20_000, kind: 'connection', state: 'disconnected' },
    { at: 30_000, kind: 'connection', state: 'connected' },
    ...frame(30_001, -26_000, id), // snapshot stamped ~26 s old: refused as stale
    ...frame(31_000, -100, yaw),
  ];
  const shift = (e: ReplayEvent): ReplayEvent => (e.kind === 'item' ? { ...e, at: e.at + base, update: { ...e.update, sourceTimeMs: e.update.sourceTimeMs + base } } : { ...e, at: e.at + base });
  return { events: events.map(shift), expect: { accepted: 5, staleRejected: 4, outOfOrderRejected: 4 } };
}
